// Return the sum of the decimal digits of |n|.
int digit_sum(int n) {
    // TODO: peel digits off with % and /
    int sum = 0;
    n = std::abs(n);
    while (n){
        sum += n % 10;
        n = n / 10;
    }
    return sum;
}

